<?php
require_once __DIR__.'/../config/auth.php';
require_once __DIR__.'/../model/AdminModel.php';
require_admin();
$tabs=['dashboard'=>'Tổng quan','products'=>'Sản phẩm & tồn kho','categories'=>'Danh mục','orders'=>'Đơn hàng','staff'=>'Nhân viên'];
$requestedTab=(string)($_GET['tab']??'dashboard'); $tab=isset($tabs[$requestedTab])?$requestedTab:'dashboard';
$statuses=['pending'=>'Chờ xác nhận','confirmed'=>'Đã xác nhận','preparing'=>'Đang pha chế','shipping'=>'Đang giao','completed'=>'Hoàn tất','cancelled'=>'Đã hủy'];
$notice='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{
  check_csrf(); $action=(string)($_POST['action']??''); $id=(int)($_POST['id']??0);
  if($action==='save_product'){
   $categoryId=(int)($_POST['category_id']??0);$name=trim($_POST['name']??'');$description=trim($_POST['description']??'');$price=(float)($_POST['price']??0);$image=trim($_POST['image']??'');$featured=isset($_POST['featured'])?1:0;$active=isset($_POST['active'])?1:0;$stock=(int)($_POST['stock']??0);
   $c=$db->prepare('SELECT id FROM danh_muc WHERE id=?');$c->bind_param('i',$categoryId);$c->execute();$exists=$c->get_result()->num_rows>0;$c->close();
   $valid=$image===''||preg_match('/^photo-[A-Za-z0-9_-]+$/',$image)||filter_var($image,FILTER_VALIDATE_URL);$scheme=$image===''||preg_match('/^photo-[A-Za-z0-9_-]+$/',$image)||in_array(strtolower((string)parse_url($image,PHP_URL_SCHEME)),['http','https'],true);
   if($name===''||$price<0||$stock<0||strlen($image)>1000||!$valid||!$scheme||!$exists)throw new DomainException('Kiểm tra tên, giá, tồn kho, danh mục và link ảnh http/https.');
   adminSaveProduct($db,$id,$categoryId,$name,$description,$price,$image,$featured,$active,$stock);go('index.php?tab=products&saved=1');
  }
  if($action==='quick_inventory'){$price=(float)($_POST['price']??0);$stock=(int)($_POST['stock']??0);if($price<0||$stock<0)throw new DomainException('Giá và tồn kho phải từ 0 trở lên.');$s=$db->prepare('UPDATE san_pham SET price=?,stock=? WHERE id=?');$s->bind_param('dii',$price,$stock,$id);$s->execute();$s->close();go('index.php?tab=products&saved=1');}
  if($action==='toggle_product'){$s=$db->prepare('UPDATE san_pham SET active=1-active WHERE id=?');$s->bind_param('i',$id);$s->execute();$s->close();go('index.php?tab=products&saved=1');}
  if($action==='delete_product'){$s=$db->prepare('DELETE FROM san_pham WHERE id=?');$s->bind_param('i',$id);$s->execute();$s->close();go('index.php?tab=products&saved=1');}
  if($action==='save_category'){$name=trim($_POST['name']??'');if($name==='')throw new DomainException('Nhập tên danh mục.');adminSaveCategory($db,$id,$name,trim($_POST['description']??''),isset($_POST['active'])?1:0);go('index.php?tab=categories&saved=1');}
  if($action==='delete_category'){$s=$db->prepare('DELETE FROM danh_muc WHERE id=?');$s->bind_param('i',$id);$s->execute();$s->close();go('index.php?tab=categories&saved=1');}
  if($action==='save_order'){$status=(string)($_POST['status']??'');if(!isset($statuses[$status]))throw new DomainException('Trạng thái đơn không hợp lệ.');adminSaveOrderStatus($db,$id,$status);go('index.php?tab=orders&saved=1');}
  if($action==='save_staff'){$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$phone=trim($_POST['phone']??'');$password=(string)($_POST['password']??'');$employmentType=(string)($_POST['employment_type']??'full_time');$shiftStart=(string)($_POST['shift_start']??'');$shiftEnd=(string)($_POST['shift_end']??'');$validTime=static fn($time)=>preg_match('/^(?:[01][0-9]|2[0-3]):[0-5][0-9]$/',$time)===1;if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||!in_array($employmentType,['part_time','full_time'],true)||!$validTime($shiftStart)||!$validTime($shiftEnd)||(!$id&&strlen($password)<8)||($password!==''&&strlen($password)<8))throw new DomainException('Kiểm tra họ tên, email, loại hình, ca làm và mật khẩu (ít nhất 8 ký tự khi tạo mới).');adminSaveStaff($db,$id,$name,$email,$phone,$employmentType,$shiftStart,$shiftEnd,$password);go('index.php?tab=staff&saved=1');}
  if($action==='delete_staff'){if($id===(int)user()['id'])throw new DomainException('Không thể xóa tài khoản admin đang đăng nhập.');$s=$db->prepare("SELECT COUNT(*) total FROM nguoi_dung WHERE role='admin'");$s->execute();$n=(int)$s->get_result()->fetch_assoc()['total'];$s->close();if($n<=1)throw new DomainException('Cần giữ lại ít nhất một tài khoản admin.');try{$s=$db->prepare("DELETE FROM nguoi_dung WHERE id=? AND role='admin'");$s->bind_param('i',$id);$s->execute();$s->close();}catch(mysqli_sql_exception $deleteError){$s=$db->prepare("UPDATE nguoi_dung SET role='customer' WHERE id=? AND role='admin'");$s->bind_param('i',$id);$s->execute();$s->close();}go('index.php?tab=staff&saved=1');}
  throw new DomainException('Thao tác không hợp lệ.');
 }catch(Throwable $ex){$notice=$ex instanceof DomainException?$ex->getMessage():'Không thể hoàn tất thao tác. Có thể dữ liệu đang được đơn hàng tham chiếu hoặc email đã tồn tại.';}
}
$today=date('Y-m-d');$from=(string)($_GET['from']??date('Y-m-01'));$to=(string)($_GET['to']??$today);$period=(string)($_GET['period']??'day');
if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$from))$from=date('Y-m-01');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$to))$to=$today;if($from>$to){$tmp=$from;$from=$to;$to=$tmp;}if(!in_array($period,['day','month','year'],true))$period='day';
$categories=adminCategories($db);$products=adminProducts($db);$staff=adminStaff($db);$orders=adminOrders($db,$from,$to,(string)($_GET['status']??''));
$editId=(int)($_GET['edit']??0);$editing=null;if($editId){$list=$tab==='categories'?$categories:($tab==='staff'?$staff:$products);foreach($list as $item)if((int)$item['id']===$editId){$editing=$item;break;}}
$stats=adminDashboardStats($db,$from,$to);$series=adminRevenueSeries($db,$from,$to,$period);
