<div class="cards"><article class="metric"><div class="metric-head">Doanh thu đã hoàn tất<span class="metric-icon">₫</span></div><strong><?=money($stats['revenue'])?></strong><small><?=date('d/m/Y',strtotime($from))?> – <?=date('d/m/Y',strtotime($to))?></small></article><article class="metric"><div class="metric-head">Đơn trong khoảng lọc<span class="metric-icon">▣</span></div><strong><?=number_format((int)$stats['orders'])?></strong><small><?=number_format((int)$stats['pending'])?> đơn chờ xác nhận</small></article><article class="metric"><div class="metric-head">Sản phẩm đang quản lý<span class="metric-icon">☕</span></div><strong><?=number_format((int)$stats['products'])?></strong><small>Tổng tồn kho <?=number_format((int)$stats['stock'])?> sản phẩm</small></article><article class="metric"><div class="metric-head">Sắp hết hàng<span class="metric-icon">!</span></div><strong><?=number_format((int)$stats['low_stock'])?></strong><small>Còn dưới 5 sản phẩm</small></article></div>
<div class="dashboard-grid"><section class="card"><div class="card-title"><div><h2>Biểu đồ doanh thu</h2><p>Chỉ tính đơn có trạng thái hoàn tất</p></div><span class="legend"><i class="dot"></i> Doanh thu</span></div><?php $vals=array_map(fn($x)=>(float)$x['revenue'],$series);$max=max($vals?:[0]);$pts=[];$n=max(1,count($series)-1);foreach($series as $i=>$point){$x=32+$i*(680/$n);$y=185-($max>0?(float)$point['revenue']/$max*155:0);$pts[]=round($x,1).','.round($y,1);}?><svg class="chart" viewBox="0 0 740 225" role="img" aria-label="Biểu đồ doanh thu"><line class="chart-grid" x1="30" y1="30" x2="715" y2="30"/><line class="chart-grid" x1="30" y1="80" x2="715" y2="80"/><line class="chart-grid" x1="30" y1="130" x2="715" y2="130"/><line class="chart-grid" x1="30" y1="185" x2="715" y2="185"/><polyline fill="none" stroke="#00704a" stroke-width="3" stroke-linecap="round" stroke-linejoin="round" points="<?=e(implode(' ',$pts))?>"/><?php if($series):?><text x="30" y="215"><?=e($series[0]['label'])?></text><text x="650" y="215"><?=e($series[count($series)-1]['label'])?></text><text x="34" y="22"><?=money($max)?></text><?php else:?><text x="280" y="110">Chưa có doanh thu hoàn tất trong khoảng thời gian này</text><?php endif;?></svg></section><section class="card"><div class="card-title"><div><h2>Tình trạng đơn hàng</h2><p>Thống kê toàn bộ đơn</p></div><a class="btn small" href="?tab=orders">Xem đơn</a></div><div class="mini-list"><?php foreach($statuses as $key=>$label):$count=0;foreach($stats['statuses'] as $r)if($r['status']===$key)$count=(int)$r['total'];?><div><div class="mini-row"><span><?=e($label)?></span><b><?=$count?></b></div><div class="bar"><i style="width:<?=min(100,(int)$stats['orders']?round($count/(int)$stats['orders']*100):0)?>%"></i></div></div><?php endforeach;?></div></section></div>
